const items = $input.all().map(i => i.json);
const client_id = items[0]?.client_id;
const conta_anuncio = items[0]?.conta_anuncio;
if (!client_id || !conta_anuncio) return [{ json: { erro: 'webhook precisa de client_id e conta_anuncio no body' } }];
return [{ json: { id: client_id, conta_anuncio, cliente: items[0]?.cliente || '' } }];

const META_TOKEN = $env.META_ACCESS_TOKEN || 'EAAU7CTYOnEwBRcirsZAzAFjAbBJ0ifBZA91HdZB9Nea3NBMMgfkV2xKy9IJZAElrCIZA7PBIwj94MFeJwL4FWR2ryuVkAIkz1PXHBUwZA1CbL2cn2iMkUZCKzc1bGLTbwrxHNIkbF1sKYIyA37sSxN7nI3Byq6LRmMeeR1tVJahLaexM9Fvnzt0F5kTjkuU';
const BASE = 'https://graph.facebook.com/v21.0';
const c = $input.item.json;
const clientId = c.id;
const clientName = c.cliente || '';
let acct = c.conta_anuncio || '';
if (!acct) return { json: { status: 'sem_conta', cliente: clientName, cliente_id: clientId, metricas: [], total_metricas: 0, last_sync_at: new Date().toISOString() } };
if (!acct.startsWith('act_')) acct = 'act_' + acct.replace('act_', '');
const helpers = this.helpers;
async function fb(url, qs) { try { return await helpers.httpRequest({ method: 'GET', url, qs, ignoreHttpStatusErrors: true, timeout: 30000 }); } catch (e) { return { error: String(e && e.message || e) }; } }
const result = { status: 'ok', cliente: clientName, cliente_id: clientId, metricas: [], total_metricas: 0, last_sync_at: new Date().toISOString(), errors: [] };
for (const cfg of [['last_30d','30d'], ['last_7d','7d']]) {
  const r = await fb(BASE + '/' + acct + '/insights', { access_token: META_TOKEN, level: 'account', date_preset: cfg[0], fields: 'reach,impressions,spend' });
  if (r && r.data && r.data[0]) {
    const row = r.data[0];
    result['account_reach_' + cfg[1]] = parseInt(row.reach || 0);
    result['account_impressions_' + cfg[1]] = parseInt(row.impressions || 0);
    result['account_spend_' + cfg[1]] = parseFloat(row.spend || 0);
  } else if (r && r.error) { result.errors.push('account ' + cfg[1] + ': ' + r.error); }
}
const acc = await fb(BASE + '/' + acct, { access_token: META_TOKEN, fields: 'name,balance,currency,account_status,amount_spent,spend_cap,funding_source_details' });
if (acc && !acc.error) {
  result.account_currency = acc.currency || 'BRL';
  result.account_status = parseInt(acc.account_status || 0);
  result.account_amount_spent = parseFloat(acc.amount_spent || 0) / 100;
  result.account_spend_cap = parseFloat(acc.spend_cap || 0) / 100;
  let balance = 0;
  const fs = acc.funding_source_details || {};
  const display = fs.display_string || '';
  if (display) { result.account_funding_display = display; const m = display.match(/R\$\s*([\d.,]+)/); if (m) { balance = parseFloat(m[1].replace(/\./g, '').replace(',', '.')) || 0; } }
  if (!balance && acc.balance) balance = parseFloat(acc.balance) / 100;
  result.account_balance = balance;
  if (fs.type === 1) result.account_funding_type = 'prepaid';
  else if (fs.type) result.account_funding_type = 'postpaid';
}
const camps = await fb(BASE + '/' + acct + '/campaigns', { access_token: META_TOKEN, fields: 'id,name,status,objective', limit: '100' });
if (!camps || !camps.data) { result.errors.push('no campaigns: ' + JSON.stringify(camps && camps.error || camps)); return { json: result }; }
function sumLeads(actions) {
  if (!actions || !actions.length) return { valor: 0, nome: null };
  const m = {};
  for (const a of actions) m[a.action_type] = parseFloat(a.value || 0);
  const cats = [
    ['lead','leads','onsite_conversion.lead_grouped','offsite_conversion.fb_pixel_lead','submit_application'],
    ['onsite_conversion.messaging_conversation_started_7d','onsite_conversion.messaging_conversation_started_1d','omnichannel_messaging_conversation_started_7d','omnichannel_messaging_conversation_started','onsite_conversion.messaging_first_reply'],
    ['contact','schedule'],
    ['purchase']
  ];
  let total = 0; const nomes = [];
  for (const cat of cats) { for (const k of cat) { if ((m[k]||0) > 0) { total += m[k]; nomes.push(k); break; } } }
  if (total <= 0) return { valor: 0, nome: null };
  return { valor: total, nome: nomes.join(',') };
}
for (const camp of camps.data) {
  let resp = await fb(BASE + '/' + camp.id + '/insights', { access_token: META_TOKEN, fields: 'date_start,spend,impressions,reach,clicks,actions', time_increment: '1', date_preset: 'last_30d', limit: '100' });
  if (!resp || !resp.data) continue;
  const rows = resp.data.slice();
  let next = resp.paging && resp.paging.next;
  while (next) { const u = new URL(next); const qs = {}; u.searchParams.forEach(function(v,k){ qs[k]=v; }); const page = await fb(u.origin + u.pathname, qs); if (!page || !page.data) break; rows.push.apply(rows, page.data); next = page.paging && page.paging.next; }
  for (const row of rows) {
    if (!row.date_start) continue;
    const res = sumLeads(row.actions);
    result.metricas.push({ client_id: clientId, campaign_id: camp.id, campaign_name: camp.name || '', data_referencia: row.date_start, investimento: parseFloat(row.spend || 0), impressoes: parseInt(row.impressions || 0), cliques_link: parseInt(row.clicks || 0), alcance: parseInt(row.reach || 0), resultado_valor: res.valor, resultado_nome: res.nome });
  }
}
result.total_metricas = result.metricas.length;
return { json: result };
